<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>롯데월드타워 설계 과정 탐색기 — 개념 재구성</title>
<style>
:root{
  --bg:#0f1419;--panel:#182029;--panel2:#1f2a35;--ink:#eef3f7;--muted:#b4c2cf;
  --line:#3a4a5a;--accent:#ffb347;--accent2:#7fd3ff;--good:#9be39b;
}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI","Apple SD Gothic Neo","Malgun Gothic","Noto Sans KR",sans-serif;font-size:16px;line-height:1.55}
a{color:var(--accent2)}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
header{padding:14px 18px;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:8px 18px;align-items:baseline;justify-content:space-between}
header h1{font-size:1.25rem;margin:0}
.badge{font-size:.85rem;background:var(--panel2);border:1px solid var(--line);padding:3px 10px;border-radius:999px;color:var(--muted)}
.badge b{color:var(--accent)}
.note{margin:10px 18px 0;padding:10px 14px;background:#2a2316;border:1px solid #6b5530;border-radius:8px;font-size:.92rem;color:#f3e3c4}
main{display:grid;grid-template-columns:minmax(320px,1fr) minmax(360px,1.25fr);gap:14px;padding:14px 18px 24px}
@media (max-width:900px){main{grid-template-columns:1fr;padding:10px}}
section.card{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px}
h2{font-size:1.05rem;margin:0 0 8px}
h3{font-size:.95rem;margin:10px 0 4px}
.tabs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}
button{font:inherit;color:var(--ink);background:var(--panel2);border:1px solid var(--line);border-radius:7px;padding:7px 11px;cursor:pointer;min-height:40px}
button:hover{border-color:var(--accent2)}
button[aria-selected="true"],button[aria-pressed="true"]{background:#2d4258;border-color:var(--accent2);color:#fff;font-weight:600}
.svgwrap{background:#f5f2ea;border-radius:8px;overflow:hidden}
.svgwrap svg{display:block;width:100%;height:auto;max-height:62vh}
.cap{font-size:.9rem;color:var(--muted);margin-top:8px}
.cap strong{color:var(--ink)}
.floorctl{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:10px 0 4px}
.floorctl input[type=range]{flex:1;min-width:180px;accent-color:var(--accent);height:32px}
.floorinfo{font-size:.92rem;background:var(--panel2);border-radius:8px;padding:8px 10px;border:1px solid var(--line)}
.floorinfo span.k{color:var(--muted)}
.stages{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
@media (max-width:600px){.stages{grid-template-columns:repeat(3,1fr)}}
.stages button{font-size:.85rem;padding:6px 4px}
.stagedesc{margin:8px 0;font-size:.93rem}
.viewers{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:600px){.viewers{grid-template-columns:1fr}}
.viewer{background:#0b1015;border:1px solid var(--line);border-radius:8px;overflow:hidden;display:flex;flex-direction:column}
.viewer .vh{display:flex;justify-content:space-between;align-items:center;padding:6px 8px;font-size:.88rem;background:var(--panel2);gap:6px;flex-wrap:wrap}
.canvasbox{position:relative;height:440px;touch-action:none}
@media (max-width:600px){.canvasbox{height:360px}}
.canvasbox canvas{display:block;width:100%;height:100%}
.canvasbox:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}
.vctl{display:flex;gap:4px;flex-wrap:wrap}
.vctl button{min-height:36px;padding:4px 9px;font-size:.85rem}
.fallback{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:20px;color:var(--muted)}
.legend{display:flex;flex-wrap:wrap;gap:8px 14px;font-size:.85rem;color:var(--muted);margin-top:8px}
.legend i{display:inline-block;width:12px;height:12px;border-radius:2px;margin-right:5px;vertical-align:-1px}
table.map{width:100%;border-collapse:collapse;font-size:.86rem;margin-top:8px}
table.map th,table.map td{border:1px solid var(--line);padding:5px 6px;text-align:left;vertical-align:top}
table.map th{background:var(--panel2)}
table.map tr.cur td{background:#2d3a22}
footer{padding:0 18px 24px;font-size:.85rem;color:var(--muted)}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.est{color:#ffcf7a}
</style>
</head>
<body>
<header>
  <h1>롯데월드타워 설계 과정 탐색기</h1>
  <div class="badge">제작 모델: <b>claude-opus-5.5</b></div>
</header>
<p class="note"><strong>개념 재구성 안내:</strong> 이 페이지는 공개 자료(KPF·LERA 프로젝트 소개)를 참고한 <strong>설명용 개념 모델</strong>입니다. 공식 시공 도면이나 검증된 구조 설계가 아닙니다. 공개 수치는 <strong>높이 555m, 지상 123층</strong>과 "위로 갈수록 좁아지는 형태", "한국 도자기의 선 참조"뿐이며, 그 외 평면 폭·코어·기둥·아웃리거 위치·층별 높이 등은 <span class="est">추정(est.)</span>으로 표시했습니다.</p>

<main>
  <!-- 도면 -->
  <section class="card" aria-labelledby="dwgTitle">
    <h2 id="dwgTitle">설계 도면 (개념)</h2>
    <div class="tabs" role="tablist" aria-label="도면 종류">
      <button role="tab" id="tab-site" aria-selected="false" aria-controls="dwg">배치도</button>
      <button role="tab" id="tab-plan" aria-selected="true" aria-controls="dwg">기준층 평면도</button>
      <button role="tab" id="tab-elev" aria-selected="false" aria-controls="dwg">입면도</button>
      <button role="tab" id="tab-sect" aria-selected="false" aria-controls="dwg">단면도</button>
    </div>
    <div class="svgwrap" id="dwg" role="tabpanel" aria-labelledby="tab-plan"></div>
    <p class="cap" id="dwgCap"></p>

    <div class="floorctl">
      <label for="floor"><strong>기준 층 선택</strong></label>
      <input type="range" id="floor" min="1" max="123" value="60" aria-describedby="floorInfo">
      <button id="fDown" aria-label="한 층 아래">−</button>
      <button id="fUp" aria-label="한 층 위">＋</button>
    </div>
    <div class="floorinfo" id="floorInfo" aria-live="polite"></div>
  </section>

  <!-- 설계 단계와 3D -->
  <section class="card" aria-labelledby="stageTitle">
    <h2 id="stageTitle">설계 발전 단계 &amp; 3D 모델</h2>
    <div class="stages" role="group" aria-label="설계 단계 선택" id="stageBtns"></div>
    <div class="stagedesc" id="stageDesc" aria-live="polite"></div>
    <div class="viewers">
      <div class="viewer">
        <div class="vh"><span id="vStageLbl">선택 단계 모델</span>
          <span class="vctl" data-v="0"></span></div>
        <div class="canvasbox" id="v0" tabindex="0" role="img" aria-label="선택한 설계 단계의 3D 모델. 방향키 회전, +/− 확대 축소, 0 초기화"></div>
      </div>
      <div class="viewer">
        <div class="vh"><span>완성 모델 (개념)</span>
          <span class="vctl" data-v="1"></span></div>
        <div class="canvasbox" id="v1" tabindex="0" role="img" aria-label="완성된 건물의 3D 개념 모델. 방향키 회전, +/− 확대 축소, 0 초기화"></div>
      </div>
    </div>
    <div class="legend">
      <span><i style="background:#ff9d2e"></i>선택 층 (도면·두 모델 공통)</span>
      <span><i style="background:#5ad1ff"></i>코어 <span class="est">(추정)</span></span>
      <span><i style="background:#e05a5a"></i>메가기둥·아웃리거 <span class="est">(추정 위치)</span></span>
    </div>
    <p class="cap">조작: 드래그 회전 · 휠/핀치 확대 · 우클릭/두 손가락 이동. 키보드: 모델 영역에 포커스 후 ←→↑↓ 회전, +/− 확대·축소, 0 시점 초기화. <label><input type="checkbox" id="autoRot"> 자동 회전</label></p>

    <h3>도면 ↔ 단계 ↔ 완성 모델 대응표</h3>
    <table class="map" id="mapTbl"></table>
  </section>
</main>

<footer>
  출처(텍스트 참조, 실행 중 불러오지 않음): 원 설계 KPF — <a href="https://www.kpf.com/project/lotte-world-tower" target="_blank" rel="noopener">kpf.com/project/lotte-world-tower</a> · 구조 설계 LERA — <a href="https://www.lera.com/lotte-world-tower" target="_blank" rel="noopener">lera.com/lotte-world-tower</a>. 용도 구간·층고·치수는 설명용 근사/추정입니다. 제작: claude-opus-5.5
</footer>

<script src="../runtime/three-runtime.js"></script>
<script>
(function(){
"use strict";
const H=555, TOPFLOOR=123, TOPFLOOR_H=498; // 높이 555m(공개), 123층 상면 ~498m(근사)
const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- 형상 정의 (모든 폭 치수는 추정) ---------- */
const BASE=36; // 반폭 36m → 기저부 약 72m (추정)
const stages=[
 {name:'1. 매스 설정',short:'매스',s:t=>BASE,n:()=>9,notch:0,struct:false,final:false,
  desc:'대지와 용도 규모로부터 555m 높이의 단순 직육면체 매스를 세운 단계. 높이와 층수(123층)만 공개 수치이고 폭은 추정입니다.',
  dwg:'입면도: 직선 외곽 / 평면도: 모든 층 동일한 정방형'},
 {name:'2. 테이퍼',short:'테이퍼',s:t=>BASE-26*t,n:()=>7,notch:0,struct:false,final:false,
  desc:'위로 갈수록 기준층 면적을 줄이는 선형 테이퍼. 상부 용도(호텔·전망대)의 작은 바닥과 풍하중 저감에 유리한 방향(일반 원리).',
  dwg:'입면도: 직선 경사 외곽 / 평면도: 층마다 축소'},
 {name:'3. 도자기 곡선',short:'곡선',s:t=>BASE-26*Math.pow(t,1.55),n:t=>4.2-1.6*t,notch:0,struct:false,final:false,
  desc:'KPF가 언급한 한국 도자기의 부드러운 선을 참고해 직선 경사를 볼록한 곡선 테이퍼로 바꾸고, 모서리를 위로 갈수록 둥글게 만든 개념.',
  dwg:'입면도: 곡선 외곽 / 평면도: 모서리 곡률 변화'},
 {name:'4. 이음매·외피',short:'이음매',s:t=>BASE-26*Math.pow(t,1.55),n:t=>4.2-1.6*t,notch:1,struct:false,final:false,
  desc:'입면 중앙을 따라 내려오는 이음매(seam)와 층별 커튼월 분할을 더해 수직성을 강조. 이음매 깊이·폭은 추정입니다.',
  dwg:'평면도: 각 면 중앙의 오목부 / 입면도: 층 띠'},
 {name:'5. 구조 시스템',short:'구조',s:t=>BASE-26*Math.pow(t,1.55),n:t=>4.2-1.6*t,notch:1,struct:true,final:false,
  desc:'LERA 소개 범주의 개념: 중앙 철근콘크리트 코어 + 외곽 메가기둥 + 기계층의 아웃리거·벨트트러스. 기둥 개수·위치·층은 이 페이지의 추정 배치입니다.',
  dwg:'단면도: 코어·아웃리거 층 / 평면도: 코어·기둥'},
 {name:'6. 완성',short:'완성',s:t=>BASE-26*Math.pow(t,1.55),n:t=>4.2-1.6*t,notch:1,struct:false,final:true,
  desc:'상부 랜턴형 크라운(개방된 격자 개념)과 저층 포디엄을 더한 완성 형상. 크라운 시작 높이와 격자 패턴은 추정입니다.',
  dwg:'모든 도면: 최종 외곽 / 3D: 크라운·포디엄'}
];
const zones=[ // 대략적 구간(공개 안내 기반 근사)
 {name:'포디엄·로비/리테일',a:1,b:12,c:'#d9c7a3'},
 {name:'오피스',a:13,b:38,c:'#a9c4de'},
 {name:'오피스텔(주거형)',a:39,b:71,c:'#b9dab0'},
 {name:'호텔',a:72,b:101,c:'#e4b9c9'},
 {name:'프라이빗 오피스 등',a:102,b:114,c:'#cdb9e4'},
 {name:'전망대',a:115,b:123,c:'#f2d48a'}
];
const outriggerFloors=[40,72,104]; // 추정
const CROWN_T=0.9;
let stageIdx=5, floor=60, view='plan';

const fh=f=>f/TOPFLOOR*TOPFLOOR_H;       // 층 → 높이(근사, 평균 층고 ≈4.05m)
const tOf=h=>Math.min(1,h/H);
function radius(a,s,n,notch){
  const c=Math.abs(Math.cos(a)),si=Math.abs(Math.sin(a));
  let r=s/Math.pow(Math.pow(c,n)+Math.pow(si,n),1/n);
  if(notch){const q=Math.PI/2;let d=((a%q)+q)%q;d=Math.min(d,q-d);r*=1-0.06*Math.exp(-(d*d)/0.003);}
  return r;
}
function outline(st,t,seg=128){
  const s=st.s(t),n=st.n(t),p=[];
  for(let i=0;i<seg;i++){const a=i/seg*Math.PI*2;const r=radius(a,s,n,st.notch);p.push([r*Math.cos(a),r*Math.sin(a)]);}
  return p;
}
const zoneOf=f=>zones.find(z=>f>=z.a&&f<=z.b)||zones[0];
const coreHalf=t=>15-6*t; // 추정
function columns(st,t){ // 8개 메가기둥 추정
  const s=st.s(t)*0.82,o=0.42,r=[];
  [[1,o],[1,-o],[-1,o],[-1,-o]].forEach(([a,b])=>{r.push([a*s,b*s]);r.push([b*s,a*s]);});
  return r;
}

/* ---------- SVG 도면 ---------- */
const NS='http://www.w3.org/2000/svg';
const dwg=document.getElementById('dwg'), cap=document.getElementById('dwgCap');
const pts=a=>a.map(p=>p[0].toFixed(2)+','+p[1].toFixed(2)).join(' ');
function profile(st,maxT){ // 입면 외곽 (면 중앙 방향, 정면)
  const L=[],R=[];
  for(let i=0;i<=80;i++){const t=i/80*maxT,h=t*H;const w=radius(Math.PI/2*0.5,0,1,0)*0+ (function(){let m=0;for(let k=0;k<64;k++){const a=k/64*Math.PI*2;m=Math.max(m,radius(a,st.s(t),st.n(t),st.notch)*Math.abs(Math.cos(a)));}return m;})();
    R.push([w,-h]);L.unshift([-w,-h]);}
  return L.concat(R);
}
function drawPlan(){
  const st=stages[stageIdx],fin=stages[5],t=tOf(fh(floor));
  const o=outline(st,t),of=outline(fin,t),s=st.s(t);
  let g='';
  for(let x=-50;x<=50;x+=10){g+=`<line x1="${x}" y1="-50" x2="${x}" y2="50" stroke="#d9d3c4" stroke-width=".2"/><line x1="-50" y1="${x}" x2="50" y2="${x}" stroke="#d9d3c4" stroke-width=".2"/>`;}
  const ch=coreHalf(t);
  const cols=columns(fin,t).map(c=>`<rect x="${c[0]-1.6}" y="${c[1]-1.6}" width="3.2" height="3.2" fill="#c0392b"/>`).join('');
  const w=(2*radius(0,s,st.n(t),st.notch)).toFixed(1);
  return `<svg viewBox="-56 -56 112 118" role="img" aria-label="${floor}층 기준층 평면 개념도">
  <title>${floor}층 기준층 평면 (개념)</title>${g}
  ${stageIdx<5?`<polygon points="${pts(of)}" fill="none" stroke="#777" stroke-width=".35" stroke-dasharray="1.5 1"/>`:''}
  <polygon points="${pts(o)}" fill="#dce7f0" stroke="#1d3a55" stroke-width=".7"/>
  ${stageIdx>=3?`<rect x="${-ch}" y="${-ch}" width="${2*ch}" height="${2*ch}" fill="#bfe9fb" stroke="#1b6d8f" stroke-width=".5"/><text x="0" y="1" font-size="3" text-anchor="middle" fill="#0d3d52">코어(추정)</text>`:''}
  ${stageIdx>=4?cols:''}
  <line x1="${-w/2}" y1="50" x2="${w/2}" y2="50" stroke="#333" stroke-width=".3"/>
  <line x1="${-w/2}" y1="48" x2="${-w/2}" y2="52" stroke="#333" stroke-width=".3"/><line x1="${w/2}" y1="48" x2="${w/2}" y2="52" stroke="#333" stroke-width=".3"/>
  <text x="0" y="55" font-size="3.2" text-anchor="middle" fill="#222">면 중앙 폭 ≈ ${w} m (추정)</text>
  <text x="-54" y="-51" font-size="3.4" fill="#222">${floor}F · 높이 ≈ ${fh(floor).toFixed(0)} m</text>
  <g transform="translate(46,-44)"><polygon points="0,-5 2,1 -2,1" fill="#222"/><text y="5" font-size="3" text-anchor="middle">N</text></g>
  <g transform="translate(-50,58)"><rect width="10" height="1" fill="#222"/><rect x="10" width="10" height="1" fill="#fff" stroke="#222" stroke-width=".2"/><text x="22" y="1.2" font-size="2.6">0–20 m · 격자 10 m</text></g>
  </svg>`;
}
function vFrame(inner,label){
  return `<svg viewBox="-150 -590 340 630" role="img" aria-label="${label}"><title>${label}</title>
  <line x1="-140" y1="0" x2="180" y2="0" stroke="#222" stroke-width="1.2"/>${inner}</svg>`;
}
function selLine(){const y=-fh(floor);return `<line x1="-120" y1="${y}" x2="120" y2="${y}" stroke="#ff8c00" stroke-width="2"/><text x="-122" y="${y-4}" font-size="11" fill="#c25e00">${floor}F</text>`;}
function ticks(){let s='';for(let f=10;f<=120;f+=10){const y=-fh(f);s+=`<line x1="-140" y1="${y}" x2="-132" y2="${y}" stroke="#555"/><text x="-130" y="${y+3}" font-size="8" fill="#444">${f}F</text>`;}return s;}
function drawElev(){
  const st=stages[stageIdx],fin=stages[5];
  let bands='';if(stageIdx>=3)for(let f=5;f<=123;f+=5){const y=-fh(f),w=radius(0,fin.s(tOf(-y)),fin.n(tOf(-y)),0)*.98;bands+=`<line x1="${-w}" y1="${y}" x2="${w}" y2="${y}" stroke="#8aa4bb" stroke-width=".5"/>`;}
  const maxT=st.final?CROWN_T:1;
  let crown='';
  if(st.final){const p=profile(fin,1).filter(q=>-q[1]>=CROWN_T*H);for(let i=-3;i<=3;i++)crown+=`<line x1="${i*3}" y1="${-H}" x2="${i*5}" y2="${-CROWN_T*H}" stroke="#1d3a55" stroke-width=".6"/>`;crown+=`<polyline points="${pts(p)}" fill="none" stroke="#1d3a55" stroke-width="1"/>`;}
  const inner=`${ticks()}
  ${stageIdx<5?`<polygon points="${pts(profile(fin,1))}" fill="none" stroke="#888" stroke-dasharray="4 3"/>`:''}
  <polygon points="${pts(profile(st,maxT))}" fill="#dce7f0" stroke="#1d3a55" stroke-width="1.2"/>
  ${stageIdx>=3?`<line x1="0" y1="0" x2="0" y2="${-maxT*H}" stroke="#1d3a55" stroke-width="1.4"/>`:''}
  ${bands}${crown}
